// Parse Instagram webhook payload
const body = $input.first().json.body;
const entry = body.entry && body.entry[0];

if (!entry) {
  return [{ json: { skip: true, reason: 'No entry in payload' } }];
}

let eventType = 'unknown';
let senderId = null;
let senderUsername = null;
let message = null;
let timestamp = new Date().toISOString();

// Check for messaging (DM)
if (entry.messaging && entry.messaging.length > 0) {
  const msg = entry.messaging[0];
  senderId = msg.sender && msg.sender.id;
  eventType = 'dm';
  message = msg.message && msg.message.text;
  timestamp = msg.timestamp ? new Date(msg.timestamp).toISOString() : timestamp;
}

// Check for changes (comments, follows)
if (entry.changes && entry.changes.length > 0) {
  const change = entry.changes[0];
  if (change.field === 'comments') {
    eventType = 'comment';
    senderId = change.value && change.value.from && change.value.from.id;
    senderUsername = change.value && change.value.from && change.value.from.username;
    message = change.value && change.value.text;
  } else if (change.field === 'followers') {
    eventType = 'follow';
    senderId = change.value && change.value.id;
    senderUsername = change.value && change.value.username;
  }
}

return [{
  json: {
    eventType,
    senderId,
    senderUsername: senderUsername || `ig_user_${senderId}`,
    message: message || '',
    timestamp,
    skip: false
  }
}];

const response = $input.first().json;
const prevData = $('Parse Instagram Event').first().json;

let contactId = null;
let contactExists = false;

if (response._embedded && response._embedded.contacts && response._embedded.contacts.length > 0) {
  contactId = response._embedded.contacts[0].id;
  contactExists = true;
}

return [{
  json: {
    ...prevData,
    contactId,
    contactExists
  }
}];

const prevData = $('Contact Exists?').first().json;
let contactId = prevData.contactId;

// If contact was just created, extract its ID
if (!contactId) {
  const createResult = $input.first().json;
  if (createResult._embedded && createResult._embedded.contacts) {
    contactId = createResult._embedded.contacts[0].id;
  }
}

return [{
  json: {
    ...prevData,
    contactId
  }
}];

const prevData = $('Merge Contact Data').first().json;
const leadResult = $input.first().json;

let leadId = null;
if (leadResult._embedded && leadResult._embedded.leads) {
  leadId = leadResult._embedded.leads[0].id;
}

return [{
  json: {
    ...prevData,
    leadId
  }
}];

const prevData = $('Extract Lead ID').first().json;

// Skip AI processing for follows (no message to respond to)
if (prevData.eventType === 'follow') {
  return [{
    json: {
      ...prevData,
      aiResponse: 'Olá! Bem-vindo(a) ao Instituto Be Healthy! 😊 Estamos aqui para cuidar da sua saúde e bem-estar. Se tiver alguma dúvida, é só nos chamar!',
      classification: {
        lead_temperature: 'cold',
        interest_area: 'unknown',
        should_handoff: false,
        reasoning: 'New follower - initial greeting'
      }
    }
  }];
}

// For DMs and comments, call OpenAI
const openaiKey = $env.OPENAI_API_KEY;
const model = $env.OPENAI_MODEL || 'gpt-4o';

const systemPrompt = `You are an AI assistant for Instituto Be Healthy (@dr.felipefranca).

Rules:
- Welcome and engage Instagram leads using SPIN methodology
- Speak in Brazilian Portuguese
- Be empathetic, professional, welcoming
- NEVER give medical advice, prescribe treatments, or analyze exams
- Redirect medical questions to in-person consultation
- Classify the lead after each interaction

After your response, output classification:
<classification>
{"lead_temperature":"hot|warm|cold|unqualified","interest_area":"weight_loss|aesthetics|general|unknown","should_handoff":true|false,"reasoning":"brief"}
</classification>`;

const response = await fetch('https://api.openai.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${openaiKey}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `[${prevData.eventType}] ${prevData.senderUsername}: ${prevData.message}` }
    ],
    max_tokens: 500,
    temperature: 0.7
  })
});

const data = await response.json();
const aiText = data.choices[0].message.content;

// Parse classification
let classification = { lead_temperature: 'cold', interest_area: 'unknown', should_handoff: false, reasoning: 'default' };
const classMatch = aiText.match(/<classification>\s*(\{[\s\S]*?\})\s*<\/classification>/);
if (classMatch) {
  try { classification = JSON.parse(classMatch[1]); } catch(e) {}
}

const cleanResponse = aiText.replace(/<classification>[\s\S]*?<\/classification>/, '').trim();

return [{
  json: {
    ...prevData,
    aiResponse: cleanResponse,
    classification
  }
}];

const data = $input.first().json;
const { classification, leadId } = data;

const temperatureToStage = {
  cold: 'Novo Seguidor',
  warm: 'Qualificação',
  hot: 'Interesse Real',
  unqualified: 'Novo Seguidor'
};

const stageName = temperatureToStage[classification.lead_temperature] || 'Novo Seguidor';

// Map stage names to environment variable status IDs
const stageToEnvVar = {
  'Novo Seguidor': $env.KOMMO_STATUS_NOVO_SEGUIDOR,
  'Qualificação': $env.KOMMO_STATUS_QUALIFICACAO,
  'Interesse Real': $env.KOMMO_STATUS_INTERESSE_REAL
};

const statusId = stageToEnvVar[stageName] || $env.KOMMO_STATUS_NOVO_SEGUIDOR;

return [{
  json: {
    ...data,
    targetStage: stageName,
    targetStatusId: statusId
  }
}];

const data = $('Lead Classification').first().json;
const { classification, leadId } = data;

const operators = {
  weight_loss: { name: 'Andrea', userId: 14813416, stage: 'Encaminhado Andrea' },
  aesthetics: { name: 'Thais', userId: 14832028, stage: 'Encaminhado Thais' }
};

const operator = operators[classification.interest_area] || operators.weight_loss;

const stageEnvMap = {
  'Encaminhado Andrea': $env.KOMMO_STATUS_ANDREA,
  'Encaminhado Thais': $env.KOMMO_STATUS_THAIS
};

return [{
  json: {
    leadId,
    operatorName: operator.name,
    responsibleUserId: operator.userId,
    targetStatusId: stageEnvMap[operator.stage],
    handoffMessage: `Vou te conectar com ${operator.name}, que é especialista nessa área e vai poder te ajudar melhor! Ela vai entrar em contato em breve.`,
    aiResponse: data.aiResponse
  }
}];
